function Card({title,value,icon:I,meta,alert}){return <div className={`kpi ${alert?'alertKpi':''}`}><div><span>{title}</span><strong>{value}</strong>{meta&&<small>{meta}</small>}</div><I/></div>}
function useDashboardData(){const [d,setD]=useState({sales:0,orders:0,rx:0,products:0,low:0,expired:0,expiring:0,chart:[],notifications:[]});const load=async()=>{const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate()).toISOString(),soon=new Date(now.getTime()+30*86400000).toISOString().slice(0,10);const [p,b,o,r,s,si]=await Promise.all([supabase.from('products').select('id,reorder_level'),supabase.from('batches').select('id,quantity,expiry_date,product_id,products(name,reorder_level)').gt('quantity',0),supabase.from('orders').select('id,status,created_at').gte('created_at',start),supabase.from('prescriptions').select('id,status,created_at').gte('created_at',start),supabase.from('sales').select('id,total,created_at').gte('created_at',new Date(now.getFullYear(),now.getMonth(),1).toISOString()),supabase.from('sale_items').select('quantity,unit_price,created_at').gte('created_at',new Date(now.getFullYear(),now.getMonth(),1).toISOString())]);const batches=b.data||[];const low=batches.filter(x=>Number(x.quantity)<=Number(x.products?.reorder_level||0)&&Number(x.quantity)>0);const expired=batches.filter(x=>x.expiry_date&&x.expiry_date<now.toISOString().slice(0,10));const expiring=batches.filter(x=>x.expiry_date&&x.expiry_date>=now.toISOString().slice(0,10)&&x.expiry_date<=soon);const sales=s.data||[];const daily={};sales.forEach(x=>{const k=x.created_at.slice(0,10);daily[k]=(daily[k]||0)+Number(x.total||0)});const chart=Array.from({length:7},(_,i)=>{const dt=new Date(now);dt.setDate(now.getDate()-6+i);const k=dt.toISOString().slice(0,10);return {label:dt.toLocaleDateString('ar',{weekday:'short'}),value:daily[k]||0}});const notes=[...low.slice(0,7).map(x=>({type:'low',text:`${x.products?.name||'دواء'} وصل إلى حد إعادة الطلب`,go:'inventory'})),...expired.slice(0,5).map(x=>({type:'expired',text:`تشغيلة ${x.products?.name||'دواء'} منتهية ولديها مخزون`,go:'inventory'})),...expiring.slice(0,5).map(x=>({type:'expiring',text:`تشغيلة ${x.products?.name||'دواء'} ستنتهي خلال 30 يوماً`,go:'inventory'})),...(o.data||[]).filter(x=>x.status==='new').slice(0,5).map(x=>({type:'order',text:`طلب جديد ${x.id.slice(0,8)}`,go:'orders'})),...(r.data||[]).filter(x=>!['completed','rejected'].includes(x.status||'new')).slice(0,5).map(x=>({type:'rx',text:'وصفة جديدة بحاجة للمراجعة',go:'prescriptions'}))];setD({sales:sales.filter(x=>x.created_at>=start).reduce((a,x)=>a+Number(x.total||0),0),orders:(o.data||[]).length,rx:(r.data||[]).length,products:(p.data||[]).length,low:low.length,expired:expired.length,expiring:expiring.length,chart,notifications:notes})};useEffect(()=>{load().catch(console.warn)},[]);return [d,load]}
function Dashboard({go}){const [d,load]=useDashboardData();const max=Math.max(1,...d.chart.map(x=>x.value));return <><PageHead title="لوحة التحكم" sub="نظرة ذكية وسريعة على الصيدلية" refresh={load}/><div className="kpis dashboardKpis"><Card title="مبيعات اليوم" value={`${money(d.sales)} ل.س`} icon={TrendingUp}/><Card title="طلبات اليوم" value={d.orders} icon={ShoppingCart}/><Card title="وصفات جديدة" value={d.rx} icon={FileImage}/><Card title="عدد الأصناف" value={d.products} icon={Package}/><Card title="قاربت على النفاد" value={d.low} icon={AlertTriangle} alert/><Card title="منتهية" value={d.expired} icon={AlertCircle} alert/><Card title="تنتهي قريباً" value={d.expiring} icon={CalendarClock} alert/></div><div className="dashboardGrid"><div className="card chartCard"><div className="cardHead"><div><h2>📈 المبيعات خلال آخر 7 أيام</h2><p>تجميع يومي من جدول المبيعات</p></div><Activity/></div><div className="barChart">{d.chart.map(x=><div className="barCol" key={x.label}><span>{money(x.value)}</span><div className="bar" style={{height:`${Math.max(8,x.value/max*100)}%`}}></div><small>{x.label}</small></div>)}</div></div><div className="card notificationsCard"><div className="cardHead"><div><h2>🔔 تنبيهات تحتاج إجراء</h2><p>النظام يبحث عن المشاكل بدلاً منك</p></div><span className="notifCount">{d.notifications.length}</span></div>{d.notifications.length?<div className="notificationList">{d.notifications.slice(0,10).map((n,i)=><button key={i} onClick={()=>go(n.go)} className={`notification ${n.type}`}><span>{n.type==='low'?'⚠️':n.type==='expired'?'🔴':n.type==='expiring'?'⏰':n.type==='order'?'🛒':'📸'}</span><b>{n.text}</b><ChevronLeft/></button>)}</div>:<div className="allGood">✓ لا توجد تنبيهات حرجة حالياً</div>}</div></div></>}
function PageHead({title,sub,refresh,actions}){const [busy,setBusy]=useState(false);const run=async()=>{if(!refresh)return;setBusy(true);try{await refresh()}catch(e){alert(e?.message||'تعذر تحديث البيانات')}finally{setBusy(false)}};return <div className="pageHead"><div><h1>{title}</h1><p>{sub}</p></div><div className="headActions">{actions}{refresh&&<button className="refreshBtn" onClick={run} disabled={busy}><RefreshCw className={busy?'spin':''}/>{busy?'جاري التحديث':'تحديث'}</button>}</div></div>}
function Products(){const empty={name:'',barcode:'',active_ingredient:'',strength:'',dosage_form:'',manufacturer:'',category:'',unit:'piece',reorder_level:0,sale_price:0,customer_visible:true};const [rows,setRows]=useState([]),[q,setQ]=useState(''),[show,setShow]=useState(false),[editId,setEditId]=useState(null),[form,setForm]=useState(empty),[busy,setBusy]=useState(false);const load=async()=>{let z=supabase.from('products').select('*').order('name');if(q)z=z.or(`name.ilike.%${q}%,barcode.ilike.%${q}%,active_ingredient.ilike.%${q}%`);const {data,error}=await z;if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[q]);const save=async()=>{if(!form.name.trim())return alert('أدخل اسم المنتج');setBusy(true);try{const payload={name:form.name.trim(),barcode:form.barcode||null,active_ingredient:form.active_ingredient||null,strength:form.strength||null,dosage_form:form.dosage_form||null,manufacturer:form.manufacturer||null,category:form.category||null,unit:form.unit||'piece',reorder_level:Number(form.reorder_level)||0,sale_price:Number(form.sale_price)||0,customer_visible:!!form.customer_visible};const r=editId?supabase.from('products').update(payload).eq('id',editId):supabase.from('products').insert(payload);const {error}=await r;if(error)throw error;setShow(false);await load()}catch(e){alert(e.message||'تعذر الحفظ')}finally{setBusy(false)}};const remove=async r=>{if(!confirm(`تعطيل/حذف «${r.name}»؟`))return;const {count}=await supabase.from('batches').select('id',{count:'exact',head:true}).eq('product_id',r.id);const {error}=count?await supabase.from('products').update({customer_visible:false}).eq('id',r.id):await supabase.from('products').delete().eq('id',r.id);if(error)alert(error.message);else await load()};return <><PageHead title="المنتجات" sub="إدارة الأصناف والباركود والأسعار" refresh={load}/><div className="toolbar"><div className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="بحث بالاسم أو الباركود أو المادة الفعالة…"/></div><button className="primary" onClick={()=>{setEditId(null);setForm(empty);setShow(true)}}><Plus/> منتج جديد</button></div><div className="tableWrap"><table><thead><tr><th>الدواء</th><th>الباركود</th><th>الشركة</th><th>السعر</th><th>حد الطلب</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.name}</b><small>{r.strength||''} {r.dosage_form||''}</small></td><td>{r.barcode||'—'}</td><td>{r.manufacturer||'—'}</td><td>{money(r.sale_price)}</td><td>{r.reorder_level}</td><td>{r.customer_visible?'ظاهر':'مخفي'}</td><td className="actions"><button className="iconBtn" onClick={()=>{setEditId(r.id);setForm({...empty,...r});setShow(true)}}>✏️</button><button className="iconBtn danger" onClick={()=>remove(r)}><Trash2/></button></td></tr>)}</tbody></table></div>{show&&<ProductForm form={form} setForm={setForm} save={save} close={()=>setShow(false)} edit={!!editId} busy={busy}/>}</>}
function ProductForm({form,setForm,save,close,edit,busy}){const fields=[['name','اسم المنتج'],['barcode','الباركود'],['active_ingredient','المادة الفعالة'],['strength','العيار'],['dosage_form','الشكل الصيدلاني'],['manufacturer','الشركة'],['category','التصنيف'],['unit','الوحدة'],['reorder_level','حد إعادة الطلب'],['sale_price','سعر البيع']];return <div className="modal"><div className="modalBox wide"><button className="x" onClick={close}>×</button><h2>{edit?'تعديل المنتج':'إضافة منتج'}</h2><div className="formGrid">{fields.map(([k,l])=><label key={k}>{l}<input type={['reorder_level','sale_price'].includes(k)?'number':'text'} value={form[k]??''} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}<label className="check"><input type="checkbox" checked={!!form.customer_visible} onChange={e=>setForm({...form,customer_visible:e.target.checked})}/> إظهار المنتج للزبائن</label></div><button className="primary full" onClick={save} disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ المنتج'}</button></div></div>}
function Inventory(){const empty={product_id:'',batch_number:'',expiry_date:'',quantity:0,purchase_price:0};const [rows,setRows]=useState([]),[products,setProducts]=useState([]),[show,setShow]=useState(false),[edit,setEdit]=useState(null),[adjust,setAdjust]=useState(null),[form,setForm]=useState(empty),[busy,setBusy]=useState(false);const load=async()=>{const {data,error}=await supabase.from('batches').select('id,batch_number,expiry_date,quantity,purchase_price,product_id,received_date,products(name,barcode,reorder_level)').order('expiry_date');if(error)throw error;setRows(data||[])};const loadProducts=async()=>{const {data,error}=await supabase.from('products').select('id,name,barcode').order('name');if(error)throw error;setProducts(data||[])};useEffect(()=>{Promise.all([load(),loadProducts()]).catch(console.warn)},[]);const refresh=()=>Promise.all([load(),loadProducts()]);const save=async()=>{if(!form.product_id||!form.expiry_date)return alert('أكمل بيانات الدفعة');setBusy(true);try{if(edit){const e=await supabase.from('batches').update({batch_number:form.batch_number||null,expiry_date:form.expiry_date,purchase_price:Number(form.purchase_price)||0}).eq('id',edit.id);if(e.error)throw e;if(Number(form.quantity)!==Number(edit.quantity)){const r=await supabase.rpc('adjust_stock',{p_batch_id:edit.id,p_delta:Number(form.quantity)-Number(edit.quantity),p_note:'تعديل كمية الدفعة'});if(r.error)throw r.error}}else{const r=await supabase.from('batches').insert({product_id:form.product_id,batch_number:form.batch_number||null,expiry_date:form.expiry_date,quantity:Number(form.quantity)||0,purchase_price:Number(form.purchase_price)||0,received_date:new Date().toISOString().slice(0,10)});if(r.error)throw r.error}setShow(false);await refresh()}catch(e){alert(e.message||'تعذر الحفظ')}finally{setBusy(false)}};const adjustSave=async()=>{const d=Number(adjust?.delta);if(!d)return;setBusy(true);const r=await supabase.rpc('adjust_stock',{p_batch_id:adjust.id,p_delta:d,p_note:adjust.note||'تسوية مخزون'});setBusy(false);if(r.error)alert(r.error.message);else{setAdjust(null);load()}};return <><PageHead title="المخزون" sub="التشغيلات والكميات والانتهاء" refresh={refresh} actions={<button className="primary" onClick={()=>{setEdit(null);setForm(empty);setShow(true)}}><Plus/> إضافة دفعة</button>}/><div className="tableWrap"><table><thead><tr><th>الدواء</th><th>التشغيلة</th><th>الانتهاء</th><th>الكمية</th><th>سعر الشراء</th><th>إجراء</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} className={r.expiry_date&&r.expiry_date<new Date().toISOString().slice(0,10)?'dangerRow':''}><td>{r.products?.name}</td><td>{r.batch_number||'—'}</td><td>{r.expiry_date||'—'}</td><td><b>{r.quantity}</b></td><td>{money(r.purchase_price)}</td><td className="actions"><button className="iconBtn" onClick={()=>{setEdit(r);setForm({product_id:r.product_id,batch_number:r.batch_number||'',expiry_date:r.expiry_date||'',quantity:r.quantity,purchase_price:r.purchase_price||0});setShow(true)}}>✏️</button><button className="iconBtn" onClick={()=>setAdjust({id:r.id,delta:'',note:''})}>±</button></td></tr>)}</tbody></table></div>{show&&<BatchForm form={form} setForm={setForm} products={products} save={save} close={()=>setShow(false)} edit={!!edit} busy={busy}/>} {adjust&&<div className="modal"><div className="modalBox"><button className="x" onClick={()=>setAdjust(null)}>×</button><h2>تعديل كمية المخزون</h2><label>الفرق (+ أو -)<input type="number" value={adjust.delta} onChange={e=>setAdjust({...adjust,delta:e.target.value})}/></label><label>ملاحظة<input value={adjust.note} onChange={e=>setAdjust({...adjust,note:e.target.value})}/></label><button className="primary full" onClick={adjustSave} disabled={busy}>حفظ الحركة</button></div></div>}</>}
function BatchForm({form,setForm,products,save,close,edit,busy}){return <div className="modal"><div className="modalBox wide"><button className="x" onClick={close}>×</button><h2>{edit?'تعديل الدفعة':'إضافة دفعة'}</h2><div className="formGrid"><label>المنتج<select disabled={edit} value={form.product_id} onChange={e=>setForm({...form,product_id:e.target.value})}><option value="">اختر المنتج</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>رقم التشغيلة<input value={form.batch_number} onChange={e=>setForm({...form,batch_number:e.target.value})}/></label><label>الانتهاء<input type="date" value={form.expiry_date} onChange={e=>setForm({...form,expiry_date:e.target.value})}/></label><label>الكمية<input type="number" min="0" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></label><label>سعر الشراء<input type="number" min="0" value={form.purchase_price} onChange={e=>setForm({...form,purchase_price:e.target.value})}/></label></div><button className="primary full" onClick={save} disabled={busy}>حفظ الدفعة</button></div></div>}
function POS(){const [q,setQ]=useState(''),[products,setProducts]=useState([]),[cart,setCart]=useState([]),[scanOpen,setScanOpen]=useState(false),[scan,setScan]=useState(null);const search=async()=>{if(!q.trim())return setProducts([]);const {data}=await supabase.from('products').select('*').or(`name.ilike.%${q}%,barcode.eq.${q}`).limit(10);setProducts(data||[])};useEffect(()=>{const t=setTimeout(search,250);return()=>clearTimeout(t)},[q]);const add=p=>setCart(c=>{const x=c.find(i=>i.id===p.id);return x?c.map(i=>i.id===p.id?{...i,qty:i.qty+1}:i):[...c,{...p,qty:1}]});const total=cart.reduce((a,x)=>a+Number(x.sale_price||0)*x.qty,0);const complete=async()=>{if(!cart.length)return;const {data,error}=await supabase.rpc('complete_sale_atomic',{p_items:cart.map(x=>({product_id:x.id,quantity:x.qty,unit_price:Number(x.sale_price||0)})),p_discount:0,p_customer_id:null});if(error)alert(error.message);else{alert(`تم إتمام البيع بنجاح: ${String(data).slice(0,8)}`);setCart([])}};const startScan=async()=>{if(!('BarcodeDetector' in window))return alert('هذا المتصفح لا يدعم BarcodeDetector. استخدم قارئ باركود USB أو أدخل الرقم يدوياً.');setScanOpen(true);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.getElementById('barcodeVideo');video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','upc_a','upc_e']});const loop=async()=>{if(!document.getElementById('barcodeVideo')){stream.getTracks().forEach(t=>t.stop());return}const codes=await detector.detect(video);if(codes[0]?.rawValue){setQ(codes[0].rawValue);setScan(codes[0].rawValue);setScanOpen(false);stream.getTracks().forEach(t=>t.stop());}};const id=setInterval(loop,500);setTimeout(()=>clearInterval(id),20000)}catch(e){alert('تعذر تشغيل الكاميرا. تحقق من صلاحية الكاميرا.')}};return <><PageHead title="نقطة البيع" sub="بيع سريع مع FEFO ومنع البيع بأكثر من المخزون"/><div className="pos"><div><div className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="اسم الدواء أو الباركود…"/><button className="scanBtn" onClick={startScan}><ScanLine/> مسح</button></div>{products.map(p=><button className="result" key={p.id} onClick={()=>add(p)}><span>{p.name}</span><small>{p.barcode||''} {p.strength||''}</small></button>)}</div><div className="card"><div className="cardHead"><h2>السلة</h2><Receipt/></div>{cart.map(x=><div className="line" key={x.id}><span>{x.name} × {x.qty}</span><b>{money(Number(x.sale_price||0)*x.qty)}</b></div>)}{cart.length?<><div className="posTotal"><span>الإجمالي</span><b>{money(total)} ل.س</b></div><button className="primary full" onClick={complete}>إتمام البيع وحسم المخزون</button></>:<p>لم تتم إضافة أصناف.</p>}</div></div>{scanOpen&&<div className="modal"><div className="modalBox"><button className="x" onClick={()=>setScanOpen(false)}>×</button><h2>مسح الباركود</h2><video id="barcodeVideo" className="barcodeVideo" playsInline/><p className="muted">وجّه الكاميرا نحو الباركود.</p></div></div>}</>}
function Orders(){const [rows,setRows]=useState([]),[detail,setDetail]=useState(null);const load=async()=>{const {data,error}=await supabase.from('orders').select('*,customers(name,phone,address),order_items(*,products(name,strength))').order('created_at',{ascending:false}).limit(150);if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const status=async(id,s)=>{const {error}=await supabase.from('orders').update({status:s}).eq('id',id);if(error)alert(error.message);else load()};const labels={new:'جديد',confirmed:'مقبول',preparing:'قيد التجهيز',ready:'جاهز',completed:'تم التسليم',cancelled:'ملغى'};return <><PageHead title="الطلبات" sub="نظام طلبات حقيقي مع رقم طلب وحالات متابعة" refresh={load}/><div className="tableWrap"><table><thead><tr><th>رقم الطلب</th><th>العميل</th><th>الهاتف</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} onClick={()=>setDetail(r)} className="clickRow"><td><b>{r.public_code||`ORD-${r.id.slice(0,6).toUpperCase()}`}</b></td><td>{r.customers?.name||'—'}</td><td>{r.customers?.phone||'—'}</td><td>{money(r.total)} ل.س</td><td><select value={r.status} onChange={e=>status(r.id,e.target.value)}>{Object.entries(labels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></td><td>{new Date(r.created_at).toLocaleString('ar')}</td></tr>)}</tbody></table></div>{detail&&<Modal onClose={()=>setDetail(null)} title={`الطلب ${detail.public_code||detail.id.slice(0,8)}`}><div className="detailGrid"><div><b>العميل</b><span>{detail.customers?.name||'—'}</span></div><div><b>الهاتف</b><span>{detail.customers?.phone||'—'}</span></div><div><b>العنوان</b><span>{detail.customers?.address||'—'}</span></div></div><h3>الأصناف</h3>{(detail.order_items||[]).map(i=><div className="line" key={i.id}><span>{i.products?.name||'—'} × {i.quantity}</span><b>{money(i.unit_price*i.quantity)}</b></div>)}</Modal>}</>}
function Prescriptions(){const [rows,setRows]=useState([]),[file,setFile]=useState(null),[busy,setBusy]=useState(false),[detail,setDetail]=useState(null);const load=async()=>{const {data,error}=await supabase.from('prescriptions').select('*').order('created_at',{ascending:false}).limit(150);if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const upload=async()=>{if(!file)return alert('اختر ملفاً');setBusy(true);try{const {data:{user}}=await supabase.auth.getUser();const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`admin/${crypto.randomUUID()}-${safe}`;let r=await supabase.storage.from('prescriptions').upload(path,file,{contentType:file.type});if(r.error)throw r.error;r=await supabase.from('prescriptions').insert({file_path:path,file_name:file.name,mime_type:file.type,file_size:file.size,created_by:user.id,status:'new'});if(r.error)throw r.error;setFile(null);await load();alert('تم رفع الوصفة')}catch(e){alert(e.message)}finally{setBusy(false)}};const view=async p=>{const {data,error}=await supabase.storage.from('prescriptions').createSignedUrl(p,300);if(error)alert(error.message);else window.open(data.signedUrl,'_blank','noopener,noreferrer')};const status=async(id,s)=>{const {error}=await supabase.from('prescriptions').update({status:s}).eq('id',id);if(error)alert(error.message);else load()};const labels={new:'جديدة',reviewing:'قيد المراجعة',ready:'تم تجهيزها',completed:'تم التسليم',rejected:'مرفوضة'};return <><PageHead title="الوصفات الطبية" sub="وصفات العملاء مع دورة مراجعة واضحة" refresh={load}/><div className="upload card"><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button className="primary" onClick={upload} disabled={!file||busy}><Upload/> رفع وصفة إدارية</button></div><div className="tableWrap"><table><thead><tr><th>العميل</th><th>الهاتف</th><th>الملف</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.customer_name||'—'}</td><td>{r.customer_phone||'—'}</td><td>{r.file_name||'—'}</td><td><select value={r.status||'new'} onChange={e=>status(r.id,e.target.value)}>{Object.entries(labels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></td><td>{new Date(r.created_at).toLocaleString('ar')}</td><td><button className="iconBtn" onClick={()=>view(r.file_path)}><Eye/></button></td></tr>)}</tbody></table></div></>}
function Requests(){const [rows,setRows]=useState([]);const load=async()=>{const {data,error}=await supabase.from('medicine_requests').select('*').order('created_at',{ascending:false});if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const done=async id=>{const {error}=await supabase.from('medicine_requests').update({status:'contacted'}).eq('id',id);if(error)alert(error.message);else load()};return <><PageHead title="طلبات البحث عن دواء" sub="كل ما لم يجده الزبون في الكتالوج" refresh={load}/><div className="tableWrap"><table><thead><tr><th>الدواء</th><th>التركيز</th><th>الهاتف</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.name}</b></td><td>{r.strength||'—'}</td><td>{r.phone}</td><td>{r.status}</td><td>{new Date(r.created_at).toLocaleString('ar')}</td><td><button className="primary miniBtn" onClick={()=>done(r.id)}>تم التواصل</button></td></tr>)}</tbody></table></div></>}
function Offers(){const empty={title:'',description:'',active:true};const [rows,setRows]=useState([]),[form,setForm]=useState(empty),[show,setShow]=useState(false);const load=async()=>{const {data,error}=await supabase.from('offers').select('*').order('created_at',{ascending:false});if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const save=async()=>{if(!form.title.trim())return;const {error}=await supabase.from('offers').insert({title:form.title.trim(),description:form.description.trim()||null,active:form.active});if(error)alert(error.message);else{setShow(false);setForm(empty);load()}};const toggle=async r=>{await supabase.from('offers').update({active:!r.active}).eq('id',r.id);load()};const del=async r=>{if(confirm('حذف العرض؟')){await supabase.from('offers').delete().eq('id',r.id);load()}};return <><PageHead title="العروض" sub="تحكم بالعروض التي تظهر تلقائياً في الموقع" refresh={load} actions={<button className="primary" onClick={()=>setShow(true)}><Plus/> عرض جديد</button>}/><div className="offerAdminGrid">{rows.map(r=><div className="offerAdmin" key={r.id}><Tag/><b>{r.title}</b><p>{r.description||'—'}</p><span className={r.active?'activePill':'mutedPill'}>{r.active?'ظاهر على الموقع':'متوقف'}</span><div><button onClick={()=>toggle(r)}>{r.active?'إيقاف':'تفعيل'}</button><button onClick={()=>del(r)}><Trash2/></button></div></div>)}</div>{show&&<Modal onClose={()=>setShow(false)} title="إضافة عرض"><label>عنوان العرض<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>الوصف<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label className="check"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/> إظهار فوراً</label><button className="primary full" onClick={save}>حفظ العرض</button></Modal>}</>}
function Reports(){const [period,setPeriod]=useState('month'),[data,setData]=useState({sales:0,purchases:0,profit:0,stock:0,best:[],worst:[],rows:[]});const load=async()=>{const now=new Date();let start=new Date(now.getFullYear(),now.getMonth(),1);if(period==='today')start=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(period==='week'){start=new Date(now);start.setDate(now.getDate()-6)}const [s,si,b,p]=await Promise.all([supabase.from('sales').select('*').gte('created_at',start.toISOString()),supabase.from('sale_items').select('product_id,quantity,unit_price,unit_cost,products(name)').gte('created_at',start.toISOString()),supabase.from('batches').select('quantity,purchase_price'),supabase.from('purchases').select('total').gte('created_at',start.toISOString())]);const sales=s.data||[],items=si.data||[];const by={};items.forEach(i=>{const n=i.products?.name||'—';by[n]=(by[n]||0)+Number(i.quantity||0)});const sorted=Object.entries(by).sort((a,b)=>b[1]-a[1]);setData({sales:sales.reduce((a,x)=>a+Number(x.total||0),0),purchases:(p.data||[]).reduce((a,x)=>a+Number(x.total||0),0),profit:items.reduce((a,x)=>a+(Number(x.unit_price||0)-Number(x.unit_cost||0))*Number(x.quantity||0),0),stock:(b.data||[]).reduce((a,x)=>a+Number(x.quantity||0)*Number(x.purchase_price||0),0),best:sorted.slice(0,10),worst:sorted.slice(-10).reverse(),rows:sales})};useEffect(()=>{load().catch(console.warn)},[period]);const exportCsv=()=>{const rows=[['التاريخ','الإجمالي'],...data.rows.map(x=>[x.created_at,x.total])];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='pharmacy-abdelhadi-report.csv';a.click()};return <><PageHead title="التقارير" sub="المبيعات والأرباح والمخزون" refresh={load} actions={<><select className="periodSelect" value={period} onChange={e=>setPeriod(e.target.value)}><option value="today">اليوم</option><option value="week">آخر 7 أيام</option><option value="month">هذا الشهر</option></select><button className="secondaryAction" onClick={exportCsv}><Download/> Excel</button><button className="secondaryAction" onClick={()=>window.print()}><FileDown/> PDF</button></>}/><div className="kpis reportKpis"><Card title="المبيعات" value={`${money(data.sales)} ل.س`} icon={TrendingUp}/><Card title="المشتريات" value={`${money(data.purchases)} ل.س`} icon={Truck}/><Card title="الربح التقديري" value={`${money(data.profit)} ل.س`} icon={Activity}/><Card title="قيمة المخزون" value={`${money(data.stock)} ل.س`} icon={Package}/></div><div className="reportGrid"><ReportList title="الأكثر مبيعاً" rows={data.best}/><ReportList title="الأقل مبيعاً" rows={data.worst}/></div><div className="tableWrap"><table><thead><tr><th>التاريخ</th><th>الإجمالي</th></tr></thead><tbody>{data.rows.map(r=><tr key={r.id}><td>{new Date(r.created_at).toLocaleString('ar')}</td><td>{money(r.total)} ل.س</td></tr>)}</tbody></table></div></>}
function ReportList({title,rows}){return <div className="card"><h2>{title}</h2>{rows.length?rows.map(([n,q],i)=><div className="reportItem" key={n}><span>{i+1}. {n}</span><b>{q}</b></div>):<p className="muted">لا توجد بيانات.</p>}</div>}
function Suppliers(){const [rows,setRows]=useState([]),[name,setName]=useState('');const load=async()=>{const {data,error}=await supabase.from('suppliers').select('*').order('name');if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const add=async()=>{if(!name.trim())return;const {error}=await supabase.from('suppliers').insert({name:name.trim()});if(error)alert(error.message);else{setName('');load()}};return <><PageHead title="الموردون" sub="شركات وموردي الأدوية" refresh={load}/><div className="toolbar"><input className="simpleInput" value={name} onChange={e=>setName(e.target.value)} placeholder="اسم المورد"/><button className="primary" onClick={add}><Plus/> إضافة</button></div><div className="tableWrap"><table><thead><tr><th>المورد</th><th>الهاتف</th><th>العنوان</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.name}</td><td>{r.phone||'—'}</td><td>{r.address||'—'}</td></tr>)}</tbody></table></div></>}
function Customers(){const [rows,setRows]=useState([]);const load=async()=>{const {data,error}=await supabase.from('customers').select('*').order('created_at',{ascending:false}).limit(150);if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);return <><PageHead title="العملاء" sub="بيانات العملاء" refresh={load}/><div className="tableWrap"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>العنوان</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.name}</td><td>{r.phone||'—'}</td><td>{r.address||'—'}</td></tr>)}</tbody></table></div></>}
function Security(){const [logs,setLogs]=useState([]);const load=async()=>{const {data,error}=await supabase.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(150);if(error)throw error;setLogs(data||[])};useEffect(()=>{load().catch(console.warn)},[]);return <><PageHead title="الأمان والتدقيق" sub="صلاحيات الإدارة وسجل العمليات" refresh={load}/><div className="card"><h2>حماية النظام</h2><p>الوصول الإداري يعتمد على Supabase Auth + app_metadata.role = admin. ملفات الوصفات خاصة.</p></div><div className="tableWrap"><table><thead><tr><th>العملية</th><th>النوع</th><th>التاريخ</th></tr></thead><tbody>{logs.map(r=><tr key={r.id}><td>{r.action}</td><td>{r.entity_type||'—'}</td><td>{new Date(r.created_at).toLocaleString('ar')}</td></tr>)}</tbody></table></div></>}
function Login(){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[err,setErr]=useState('');const submit=async e=>{e.preventDefault();setErr('');const {error}=await supabase.auth.signInWithPassword({email,password});if(error)setErr(error.message)};return <div className="login"><form onSubmit={submit}><div className="logo">ص</div><h1>صيدلية عبدالهادي</h1><p>تسجيل دخول الإدارة</p><input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e=>setEmail(e.target.value)} required/><input type="password" placeholder="كلمة المرور" value={password} onChange={e=>setPassword(e.target.value)} required/><button className="primary full"><LogIn/> دخول</button>{err&&<div className="error">{err}</div>}</form></div>}
// If a session exists but is not admin, show login instead of exposing admin.
const Root=()=>{const [s,setS]=useState(null),[checked,setChecked]=useState(false);useEffect(()=>{supabase?.auth.getSession().then(({data})=>{setS(data.session);setChecked(true)});if(supabase){const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,ss)=>setS(ss));return()=>subscription.unsubscribe()}},[]);if(!checked)return <Splash/>;if(s?.user?.app_metadata?.role==='admin')return <Admin onLogout={()=>supabase.auth.signOut()}/>;return <CustomerOrLogin/>};
function CustomerOrLogin(){const [login,setLogin]=useState(location.hash==='#admin');return login?<><Login/><button className="back" onClick={()=>{location.hash='';setLogin(false)}}>العودة للموقع</button></>:<><Customer/><button className="adminLink" onClick={()=>{location.hash='admin';setLogin(true)}}>دخول الإدارة</button></>}
createRoot(document.getElementById('root')).render(<Root/>);
